"""Create a local-only blind listening aid from actual normalized study audio."""
import pathlib,json,random,shutil,hashlib
ROOT=pathlib.Path(__file__).resolve().parents[1];REPORT=ROOT/'docs/research-runs/2026-10-29-current-musicality';OUT=ROOT.parent/'current-musicality-audition';OUT.mkdir(exist_ok=True);(OUT/'audio').mkdir(exist_ok=True)
plan=json.loads((REPORT/'study-plan.json').read_text());study=json.loads((REPORT/'study-results.json').read_text());assert len(study['completed'])==12 and not study['failures']
DATA=pathlib.Path.home()/'Library/Application Support/soulfire/music-lab';rng=random.Random(2026102951);groups=[]
for n,row in enumerate(plan['rows']):
 choices=[{'arm':'A · preserved original caption / shift 1','path':str(DATA/'samples'/row['baselineId']/'bed.wav'),'baselineId':row['baselineId'],'metadata':'original request/conditioning unchanged'}]
 for arm in ['B','C']:
  r=next(x for x in study['completed'] if x['baselineId']==row['baselineId'] and x['arm']==arm);assert not r['technicalIssues'];choices.append({'arm':arm+' · musical caption / shift '+('1' if arm=='B' else '3'),'path':r['bed'],'baselineId':row['baselineId'],'metadata':r['timing']['generationSettings']})
 rng.shuffle(choices)
 for i,c in enumerate(choices):
  filename=hashlib.sha256((row['baselineId']+str(i)+'2026102951').encode()).hexdigest()[:16]+'.wav';destination=OUT/'audio'/filename;shutil.copyfile(c.pop('path'),destination);c['url']='audio/'+filename;c['label']=chr(65+i);c['bedSha256']=hashlib.sha256(destination.read_bytes()).hexdigest()
 groups.append({'id':row['baselineId'],'name':row['concept'],'palette':row['request']['style'],'clips':choices})
manifest={'version':1,'purpose':'Human blind musicality comparison; no clinical outcome or automatic winner','normalization':'Identical -21 LUFS matching, true-peak headroom; not ear SPL','groups':groups};(OUT/'manifest.json').write_text(json.dumps(manifest,indent=2))
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Current · musicality listening review</title><style>
:root{color-scheme:light;--ink:#2e483d;--sage:#4c6456;--line:#d8dece}*{box-sizing:border-box}body{margin:0;background:#f6f3e8;color:var(--ink);font:16px/1.5 system-ui}header,main{max-width:1120px;margin:auto;padding:24px}h1,h2{font-family:Georgia,serif}h1{font-size:38px;line-height:1.15}h2{margin:0 0 8px}p{max-width:800px}.eyebrow{letter-spacing:.12em;font-size:12px;font-weight:700}.panel{position:sticky;top:0;background:#f6f3e8ee;backdrop-filter:blur(10px);z-index:3;border-block:1px solid var(--line);padding:14px 24px}.panel>div{max-width:1072px;margin:auto;display:flex;gap:14px;flex-wrap:wrap;align-items:center}audio{width:min(430px,100%)}button,select,textarea{font:inherit;border:1px solid var(--line);border-radius:10px;background:#fffdf8;color:var(--ink);padding:10px 14px}button{cursor:pointer;min-height:44px}button.active{background:#2f5548;color:white}button:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #bd984f;outline-offset:3px}section{border:1px solid var(--line);background:#fffdf8;border-radius:18px;padding:22px;margin:20px 0}.clips{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.clip{background:#f0f2e8;padding:16px;border-radius:12px;min-width:0}.clip button{width:100%;margin-bottom:12px}label{display:block;font-size:14px;margin-top:12px}select,textarea{display:block;width:100%;margin-top:4px}.reveal{font-size:12px;min-height:36px;overflow-wrap:anywhere}.small{font-size:13px;color:#546859}footer{padding:24px;max-width:1120px;margin:auto}#notice{font-size:14px}textarea{min-height:70px}.actions{display:flex;gap:10px;flex-wrap:wrap}@media(max-width:650px){header,main{padding:18px}.clips{grid-template-columns:1fr}h1{font-size:30px}.panel{padding:12px 18px}section{padding:16px}.clip{padding:14px}}
</style><header><span class="eyebrow">SOULFIRE · CURRENT · LOCAL LISTENING REVIEW</span><h1>Which music feels more coherent?</h1><p>Six matched-seed trios. These are real audio outputs, with matched playback loudness. Listen before revealing the generation settings. No winner has been selected and the original catalogue is unchanged.</p><p class="small">Pause other Soulfire music or voice before listening here. Start quietly; device volume still matters. Notes and chord transcriptions are uncertain aids, not a score or a health benefit claim.</p><div class="actions"><button id="reveal">Reveal settings</button><button id="download">Download my ratings</button></div><p class="small">Ratings stay in this tab's memory and export only when you choose. No account, upload or automatic saving.</p></header><div class="panel"><div><strong id="playing">Nothing playing</strong><audio id="player" controls preload="none"></audio><button id="stop">Stop all review audio</button><span id="notice" role="status"></span></div></div><main id="groups"></main><footer>Baseline, caption-only and caption-plus-shift candidates use the same original seeds. Changing a caption changes the whole musical trajectory; these are not note-for-note minimal pairs. Preference and musical quality require your listening.</footer><script>
let manifest,revealed=false;const ratings={},player=document.querySelector('#player');player.volume=.35;
function stop(){player.pause();player.removeAttribute('src');player.load();document.querySelector('#playing').textContent='Nothing playing';document.querySelectorAll('.play').forEach(b=>b.classList.remove('active'))}
document.querySelector('#stop').onclick=stop;document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});addEventListener('pagehide',stop);
function score(label,key,record){const wrap=document.createElement('label');wrap.textContent=label;const select=document.createElement('select');select.setAttribute('aria-label',label+' '+record.label);select.innerHTML='<option value="">Not rated</option>'+[1,2,3,4,5].map(n=>'<option>'+n+'</option>').join('');select.onchange=()=>{record[key]=select.value?Number(select.value):null;record.ratedAfterReveal=revealed};wrap.append(select);return wrap}
fetch('manifest.json').then(r=>r.json()).then(m=>{manifest=m;for(const [index,g] of m.groups.entries()){const section=document.createElement('section'),h=document.createElement('h2');h.textContent=(index+1)+'. '+g.name;section.append(h);const sub=document.createElement('p');sub.className='small';sub.textContent=g.palette+' · three 30-second pieces · labels randomized per trio';section.append(sub);const clips=document.createElement('div');clips.className='clips';ratings[g.id]={name:g.name,clips:{}};for(const c of g.clips){const card=document.createElement('div');card.className='clip';const button=document.createElement('button');button.className='play';button.textContent='Play '+c.label;button.setAttribute('aria-label','Play trio '+(index+1)+' choice '+c.label);button.onclick=async()=>{stop();player.src=c.url;try{await player.play();button.classList.add('active');document.querySelector('#playing').textContent=g.name+' · '+c.label;document.querySelector('#notice').textContent=''}catch{document.querySelector('#notice').textContent='Audio could not start. Try the player Play control.'}};card.append(button);const reveal=document.createElement('p');reveal.className='reveal';reveal.dataset.arm=c.arm;reveal.textContent='Settings hidden until you choose Reveal';card.append(reveal);const record=ratings[g.id].clips[c.label]={label:g.name+' '+c.label,progression:null,phrasing:null,paletteFit:null,artifacts:null,notes:'',ratedAfterReveal:false};for(const [label,key] of [['Progression makes sense · 1–5','progression'],['Phrasing and ending · 1–5','phrasing'],['Fits the sound palette · 1–5','paletteFit'],['Distracting artifacts · 1–5 (5 = most)','artifacts']])card.append(score(label,key,record));const notes=document.createElement('label');notes.textContent='Notes or odd-note timestamps';const text=document.createElement('textarea');text.setAttribute('aria-label','Notes '+g.name+' '+c.label);text.placeholder='e.g. 0:12 — unexpected note';text.oninput=()=>{record.notes=text.value;record.ratedAfterReveal=revealed};notes.append(text);card.append(notes);clips.append(card)}section.append(clips);const choice=document.createElement('label');choice.textContent='Your preferred clip';const select=document.createElement('select');select.setAttribute('aria-label','Preferred clip '+g.name);select.innerHTML='<option value="">Not chosen</option><option>A</option><option>B</option><option>C</option><option>No preference</option>';select.onchange=()=>{ratings[g.id].preferred=select.value||null;ratings[g.id].preferenceAfterReveal=revealed};choice.append(select);section.append(choice);document.querySelector('#groups').append(section)}}).catch(()=>document.querySelector('#notice').textContent='Review manifest unavailable. No samples are simulated.');
document.querySelector('#reveal').onclick=()=>{revealed=true;document.querySelectorAll('[data-arm]').forEach(e=>e.textContent=e.dataset.arm);document.querySelector('#reveal').disabled=true};document.querySelector('#download').onclick=()=>{if(!manifest)return;const output={version:1,createdAt:new Date().toISOString(),purpose:'Actual user ratings, no inferred clinical outcome',revealed,ratings,manifest};const blob=new Blob([JSON.stringify(output,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='current-musicality-my-ratings.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
</script></html>''';(OUT/'index.html').write_text(html)
(REPORT/'audition-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
print(json.dumps({'directory':str(OUT),'trios':len(groups),'realAudioFiles':sum(len(g['clips']) for g in groups)}))
